#include <stdio.h>
int biggest(const int values[], int count) {
    int best = values[0];
    for (int i = 1; i < count; i++) {
        if (values[i] > best) {
            best = values[i];
        }
    }
    return best;
}
void double_all(int values[], int count) {
    for (int i = 0; i < count; i++) {
        values[i] *= 2;
    }
}
int main(void) {
    int nuts[] = {3, 8, 2};
    printf("biggest %d\n", biggest(nuts, 3));
    double_all(nuts, 3);
    printf("now %d %d %d\n", nuts[0], nuts[1], nuts[2]);
    return 0;
}

