#include <stdio.h>
typedef struct {
    const char *name;
    int nuts;
} Tree;
void harvest(Tree *t, int amount) {
    if (amount > t->nuts) {
        amount = t->nuts;
    }
    t->nuts -= amount;
}
void show(const Tree *t) {
    printf("%s has %d nuts\n", t->name, t->nuts);
}
int main(void) {
    Tree oak = {"oak", 30};
    harvest(&oak, 12);
    show(&oak);
    harvest(&oak, 50);
    show(&oak);
    return 0;
}

